FUNCTION_BLOCK FB
VAR_INPUT
    tankLevel   : REAL;
    outletFlow  : REAL;
    inletPermit : BOOL;
    resetBtn    : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun         : BOOL;
    alarmHigh       : BOOL;
    alarmLow        : BOOL;
    outletValveOpen : BOOL;
END_VAR
VAR
    resetRisingEdge : BOOL := FALSE;
    prevResetBtn    : BOOL := FALSE;
    highCondition   : BOOL := FALSE;
    lowCondition    : BOOL := FALSE;
END_VAR

    // 边沿检测：复位按钮上升沿
    resetRisingEdge := resetBtn AND NOT prevResetBtn;
    prevResetBtn    := resetBtn;

    // 当前液位是否触发报警条件
    highCondition := (tankLevel >= 85.0);
    lowCondition  := (tankLevel <= 15.0);

    // 报警自保持：报警条件存在时置位，条件解除后等待复位上升沿清除
    IF highCondition THEN
        alarmHigh := TRUE;
    ELSIF resetRisingEdge AND NOT highCondition THEN
        alarmHigh := FALSE;
    END_IF

    IF lowCondition THEN
        alarmLow := TRUE;
    ELSIF resetRisingEdge AND NOT lowCondition THEN
        alarmLow := FALSE;
    END_IF

    // 泵控制：高液位报警时立即停止，否则在许可且液位安全时运行
    pumpRun := NOT alarmHigh AND inletPermit AND (tankLevel > 15.0);

    // 出口阀：低液位报警时关闭，无报警时开启
    outletValveOpen := NOT alarmLow;

END_FUNCTION_BLOCK
